# Generates css/goth3.css: "Goth" mood (data-theme="goth3"), the calm black + pink look.
# PURE RESKIN: only paint properties (colours, backgrounds, border colours, shadows, filters, fonts of the logo).
# No widths, paddings, margins, borders widths, display or position changes vs the pink layout.
# Studs belt + lace curtain are drawn as backgrounds / absolute overlays so nothing shifts.
G='html[data-theme="goth3"]'
ST="url(../images/goth2/studs.webp)";LC="url(../images/goth2/lace.webp)"
PK='#FF5FA2';LACE='#C24078'
CHR="linear-gradient(180deg,#f4f4f8,#8a8a96 45%,#2a2a30 55%,#c9c9d4)"
GEL="linear-gradient(180deg,rgba(255,255,255,.22),rgba(255,255,255,.04) 48%,rgba(0,0,0,0) 52%,rgba(255,255,255,.06)),linear-gradient(180deg,#2a2a30,#0c0c0e)"
PGEL="linear-gradient(180deg,rgba(255,255,255,.3),rgba(255,255,255,0) 48%),linear-gradient(180deg,#E87AAA 0%,#C24078 45%,#7A1748 100%)"
BTN=":is(.gelbtn,.btn,.btn-aero,.top-nav a,.sidebar-nav a,.combo-drop-menu a,.px-addbtn,.popup-btn,.bag-checkout,.music-pill,.px-bagbtn,.figurine-button,.px-teaser-link)"
ON=":is(.sidebar-nav a.active,.btn-primary,.gelbtn.on)"
o=f"""/* GOTH mood (data-theme="goth3"): generated by tools/build_goth3.py, a pure reskin of the pink layout. */
@font-face{{font-family:'Pirata One';src:url(../fonts/pirata-one.woff2) format('woff2');font-display:swap}}
{G}{{--pink:{PK};--hot-pink:{PK};--soft-pink:{PK};--baby-pink:#141216;--accent:{PK};--accent-soft:{PK};--accent-deep:{PK};--accent-glow:rgba(0,0,0,0);
 --text:{PK};--text-light:{PK};--text-dark:{PK};--off-white:#050505;--cream:#050505;--t-bg:#050505;--t-panel:#050505;--t-panel-2:#0c0c0e;--t-side:#050505;
 --t-title:#0c0c0e;--t-ink:{PK};--t-ink-soft:{PK};--t-line:#55555f;--t-shadow:#000;--t-heading:{PK};--t-glow:rgba(0,0,0,0);--g1:#0c0c0e;--g2:#050505;--g3:{PK}}}
{G} body *:not(img):not(canvas){{color:{PK}!important}}
{G} *,{G} *::before,{G} *::after{{text-shadow:none!important}}
/* surfaces: black */
{G} body,{G} body.home-page,{G} body.secondary-page{{background:#050505!important}}
{G} .secondary-page::before,{G} .drop-section::before,{G} .drop-section::after,{G} .cd-section::before,{G} .lotus-section::before{{opacity:0!important}}
{G} .page-wrapper,{G} .main-content,{G} .content-section,{G} .drop-section,{G} .px-teaser,{G} .lotus-section,{G} .cd-section,{G} .sidebar-section,{G} .page-layout>.sidebar,{G} .footer{{background:#050505!important;border-color:#2a2a30!important;box-shadow:none!important}}
{G} .combo-win,{G} .pc-popup,{G} .notepad{{background:#050505!important;border-color:#3a3a42!important;box-shadow:none!important}}
{G} .combo-wb,{G} .pc-popup-body,{G} .win-panel-inset{{background:#050505!important;border-color:#2a2a30!important;box-shadow:none!important}}
{G} .sidebar-title,{G} .combo-tb,{G} .pc-popup-titlebar,{G} .win-titlebar{{background:#050505!important;border-color:#2a2a30!important;box-shadow:none!important}}
{G} .combo-tb i{{background:#3a3a42!important}}
{G} .combo-tb i:first-child{{background:#3a3a42!important}}
/* studs belt: painted into the top bar, overlay strip on the sidebar edge (no layout change) */
{G} .top-nav{{background:linear-gradient(180deg,#d9d9e3 0 1px,#000 1px 2px,transparent 2px calc(100% - 2px),#000 calc(100% - 2px) calc(100% - 1px),#8d8d9c calc(100% - 1px)),{ST} 0 50%/34px auto,#111!important;box-shadow:none!important}}
{G} .page-layout>.sidebar{{position:relative}}
{G} .page-layout>.sidebar::after{{content:"";position:absolute;top:0;bottom:0;right:-9px;width:16px;z-index:5;pointer-events:none;background:linear-gradient(90deg,#d9d9e3 0 1px,#000 1px 2px,transparent 2px calc(100% - 2px),#000 calc(100% - 2px) calc(100% - 1px),#8d8d9c calc(100% - 1px)),{ST} 0 0/16px auto}}
{G} .combo-mbar{{background:linear-gradient(rgba(5,5,5,.8),rgba(5,5,5,.8)),{ST} 0 50%/30px auto!important;border-color:#c9c9d4!important;box-shadow:none!important}}
/* hero: one translucent lace curtain behind the content */
{G} .banner,{G} .banner.pink-hero{{background:#050505!important;border-color:#2a2a30!important;box-shadow:none!important;isolation:isolate}}
{G} .banner::before{{content:"";position:absolute;inset:0;background:{LC} 0 0/420px;opacity:.15;-webkit-mask-image:radial-gradient(70% 90% at 72% 50%,#000 0%,rgba(0,0,0,.5) 45%,transparent 80%);mask-image:radial-gradient(70% 90% at 72% 50%,#000 0%,rgba(0,0,0,.5) 45%,transparent 80%);pointer-events:none;z-index:-1}}
{G} .pg-hero,{G} .pg-hero[class*="pat-"]{{background:#050505!important;box-shadow:none!important}}
{G} .pg-sub,{G} .pg-hero p{{background:#050505!important;border-color:{PK}!important}}
{G} .pg-art{{background:none!important}}
/* logo: chrome Pirata One, the one big statement */
{G} .brand-logo:not(.banner-title){{line-height:1.08!important}}
{G} .brand-logo{{font-family:'Pirata One','Archivo Black',serif!important;background:linear-gradient(180deg,#ffffff 0%,#e9e9f1 30%,#8a8a98 48%,#2c2c34 52%,#cfcfdb 70%,#ffffff 100%)!important;-webkit-background-clip:text!important;background-clip:text!important;-webkit-text-fill-color:transparent!important;color:transparent!important;filter:drop-shadow(0 2px 0 #000)!important;text-shadow:none!important}}
/* buttons: flat black pills, thin grey edge; only active/primary is lace-pink gel with the dashed outline */
{G} {BTN}{{background:#0a0a0c!important;border-color:#6a6a76!important;box-shadow:none!important;outline:0!important}}
{G} .px-addbtn span,{G} .music-pill .gel{{background:#0a0a0c!important;box-shadow:none!important}}
{G} {BTN}::before,{G} {BTN}::after,{G} .px-addbtn span::before,{G} .music-pill .gel::before{{background:none!important;opacity:0!important}}
{G} {ON}{{background:{PGEL}!important;border-color:#c9c9d4!important;outline:1px dashed {PK}!important;outline-offset:3px!important}}
{G} {ON}::before{{background:linear-gradient(180deg,rgba(255,255,255,.3),rgba(255,255,255,0))!important;opacity:1!important}}
{G} .music-pill .gel{{background:{PGEL}!important}}
{G} {ON},{G} {ON} *,{G} .music-pill .gel *{{color:#000!important}}
{G} .px-addbtn span{{box-shadow:0 0 0 1px #6a6a76!important}}
{G} .pp-tag{{border-color:#3a3a42!important}}
/* top bar nav: glossy lace-pink gel pills with the dashed hot-pink outline (restored) */
{G} .top-nav a,{G} body .combo-dhead .gelbtn.combo-close,{G} .combo-mbar :is(.gelbtn,.px-bagbtn){{background:{PGEL}!important;border-color:#c9c9d4!important;outline:1px dashed {PK}!important;outline-offset:2px!important}}
{G} .top-nav a::before,{G} body .combo-dhead .gelbtn.combo-close::before,{G} .combo-mbar :is(.gelbtn,.px-bagbtn)::before{{background:linear-gradient(180deg,rgba(255,255,255,.55),rgba(255,255,255,0))!important;opacity:1!important}}
{G} .top-nav a,{G} .top-nav a *,{G} .combo-close,{G} .combo-close *,{G} .combo-mbar :is(.gelbtn,.px-bagbtn),{G} .combo-mbar :is(.gelbtn,.px-bagbtn) *{{color:#000!important}}
/* phone drawer header: dark studded bar like the top bar, chrome logo, no pink fade */
{G} .combo-dhead{{background:linear-gradient(rgba(5,5,5,.8),rgba(5,5,5,.8)),{ST} 0 50%/30px auto,#050505!important;box-shadow:inset 0 -1px 0 #c9c9d4!important}}
{G} .combo-dhead .brand-logo{{letter-spacing:.01em!important;overflow:visible!important;padding-right:.1em}}
/* product cards, tags, inputs */
{G} .pp-ph,{G} .pp-ph[class*="pat-"]{{background:#050505!important;border-color:#3a3a42!important;box-shadow:none!important}}
{G} .pp-tag{{border-style:solid!important;border-color:#3a3a42!important}}
{G} .pp-cell{{box-shadow:none!important}}
{G} .pp-tag,{G} .section-tag,{G} .px-teaser-link{{background:#050505!important;box-shadow:none!important}}
{G} .section-tag{{border-color:{PK}!important}}
{G} input,{G} textarea,{G} select{{background:#050505!important;color:{PK}!important;border-color:{PK}!important}}
{G} .draft{{background:#050505!important;border-color:{PK}!important}}
{G} .theme-switcher-inline{{background:linear-gradient(rgba(0,0,0,.25),rgba(0,0,0,.25)),{ST} 0 0/60px auto!important;border-color:#c9c9d4!important;box-shadow:none!important}}
{G} .theme-btn.active{{outline-color:{PK}!important}}
.theme-btn[data-theme="goth3"]{{background:linear-gradient(180deg,#050505 0 30%,transparent 30% 70%,#050505 70%),{ST} 0 50%/14px auto,#050505!important}}
{G} .combo-drop-menu{{background:#050505!important}}
{G} .combo-backdrop{{background:rgba(0,0,0,.55)!important}}
{G} .bag-list li,{G} .bag-note{{background:#050505!important}}
/* clouds go dark, stickers grey */
{G} .px-cloud-divider{{background:#050505!important}}
{G} .px-cloud-divider .pxc{{filter:brightness(.12);opacity:.6}}
{G} .hero-phone-sticker,{G} .inspo-shelf img,{G} .norway-sticker{{filter:grayscale(1) contrast(1.1)!important}}
/* sparkles: sparse pixel hearts and crosses (absolute canvases, no layout) */
{G} .px-goth-skull,{G} .px-spark-pink{{display:none!important}}
{G} .px-g2-spark{{display:block!important;opacity:.8}}
{G} .px-g2-spark:nth-of-type(3n),{G} .px-g2-spark:nth-of-type(3n+1){{display:none!important}}
{G} #sparkle-canvas{{opacity:.35}}
{G} .px-g2-spark{{opacity:.5!important}}
/* kitty CD: monochrome disc */
{G} .combo-fcd .cd,{G} .sidebar-cd .cd{{background:radial-gradient(circle,#050505 0 12%,#b9b9c6 12% 14%,transparent 14.5%),conic-gradient(from 20deg,#2a2a30,#d9d9e3,#55555f,#ffffff,#3a3a42,#b9b9c6,#1c1c21,#f2f2f6,#2a2a30)!important;box-shadow:0 0 0 1px #8d8d9c!important}}
{G} .sidebar-cd .badge b,{G} .combo-fcd .badge b{{background:radial-gradient(circle at 50% 110%,#d9d9e3,#6a6a76 45%,#1c1c21)!important}}
{G} .sidebar-cd .badge,{G} .combo-fcd .badge{{background:linear-gradient(180deg,#fff,#8d8d9c 50%,#e6e6ee)!important}}
{G} .px-cat{{filter:none!important}}
@media (max-width:768px){{
 {G} .page-layout>.sidebar::after{{right:auto;left:0;width:14px;background-size:14px auto}}
 {G} body::before{{content:"";position:fixed;left:0;top:0;bottom:0;width:6px;z-index:40;pointer-events:none;background:linear-gradient(90deg,transparent calc(100% - 1px),#c9c9d4 calc(100% - 1px)),{ST} 0 0/6px auto}}
}}
"""
open('css/goth3.css','w').write(o);print('ok')
